manifest = ET.parse(ROOT / 'app' / 'src' / 'main' / 'AndroidManifest.xml').getroot()
android = '{http://schemas.android.com/apk/res/android}'
permissions = {item.get(android + 'name') for item in manifest.findall('uses-permission')}
assert {'android.permission.RECORD_AUDIO', 'android.permission.FOREGROUND_SERVICE_MICROPHONE'} <= permissions
assert not {'android.permission.CAPTURE_AUDIO_OUTPUT',
            'android.permission.BYPASS_CONCURRENT_RECORD_AUDIO_RESTRICTION'} & permissions
service = next(item for item in manifest.find('application').findall('service')
               if item.get(android + 'name') == '.PolicyService')
assert set(service.get(android + 'foregroundServiceType').split('|')) == {'specialUse', 'microphone'}
build = HERE / 'call-host-build'
build.mkdir()
try:
    generated = []
    for relative, source in STUBS.items():
        if relative == 'com/smartvowificall/ims/PolicyService.java':
            continue
        p = build / relative
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(source, encoding='utf-8')
        generated.append(p)
    app = ROOT / 'app/src/main/java/com/smartvowificall/ims'
    sources = list((app / 'engine').glob('*.java')) + [app / 'NewCallSession.java', app / 'PcmAudio.java', app / 'PolicyService.java', app / 'ProcessTransport.java',
                HERE / 'EngineContractTest.java', HERE / 'CallIntegrationTest.java', HERE / 'ProcessTransportTest.java'] + generated
    api_classes = build / 'android-api-check'
    api_classes.mkdir()
    runtime_api = api_classes / 'RuntimeController.java'
    runtime_api.write_text(STUBS['com/smartvowificall/ims/RuntimeController.java'].replace(
        'new Context()', 'null'), encoding='utf-8')
    api_sources = list((app / 'engine').glob('*.java')) + [app / 'PcmAudio.java', app / 'PolicyService.java', runtime_api]
    subprocess.run([str(JAVA/'javac.exe'),'--release','11','-encoding','UTF-8',
                    '-cp',str(ROOT / 'deps' / 'android-system.jar'),'-d',str(api_classes),
                    *map(str,api_sources)],check=True)
    subprocess.run([str(JAVA/'javac.exe'),'--release','11','-encoding','UTF-8','-d',str(build),*map(str,sources)],check=True)
    subprocess.run([str(JAVA/'java.exe'),'-ea','-cp',str(build),'com.smartvowificall.ims.CallIntegrationTest'],check=True,timeout=40)
    subprocess.run([str(JAVA/'java.exe'),'-ea','-cp',str(build),'com.smartvowificall.ims.ProcessTransportTest'],check=True,timeout=10)
finally:
    shutil.rmtree(build)
